}catch{if($intentSaved -and -not(Test-Path -LiteralPath (Join-Path $root 'preservation-failed.json'))){Save-New 'preservation-failed.json' @{run_id=$run;error=$_.Exception.ToString();automatic_retry=$false;utc=[DateTime]::UtcNow.ToString('o')}};throw}
finally{if($null -ne $s){Remove-PSSession $s}}
